shell_commands:
node --input-type=module -e "
import Ajv from 'ajv';
const ajv = new Ajv({strict: false, validateFormats: false});
const v = ajv.compile({type:'object', properties:{ssn:{type:'string'}}, required:['ssn']});
const ok = v({ssn: 123456789});
console.log('valid:', ok);
console.log('errors:', JSON.stringify(v.errors, null, 1).slice(0, 600));
"

cat > scratch-probe.ts <<'EOF'
import Ajv from 'ajv';
import type {ErrorObject, ValidateFunction, Options} from 'ajv';
type T1 = typeof Ajv;
declare const o: Options;
const s: boolean | 'log' | undefined = o.strict;
declare const e: ErrorObject;
const p: string = e.instancePath;
const v: ValidateFunction = (input: unknown) => true;
console.log(T1, s, p, v);
const inst = new Ajv({strict: false, validateFormats: false});
console.log(inst);
EOF
timeout 120 npx tsc --noEmit --strict --esModuleInterop --module nodenext --moduleResolution nodenext --target es2022 scratch-probe.ts 2>&1 | head -20; rm scratch-probe.ts

cat > scratch-probe.ts <<'EOF'
