import * as AjvNS from 'ajv';
type HasDefault = 'default' extends keyof typeof AjvNS ? true : false;
const hd: HasDefault = true as HasDefault;
// ask: is the default a constructable class?
declare const d: typeof AjvNS;
type DefaultT = typeof AjvNS extends {default: infer D} ? D : never;
const inst = new ((typeof AjvNS extends {default: infer D} ? D : never))({});
type IsClass = DefaultT extends new (...a: never[]) => unknown ? true : false;
const ic: IsClass = true as IsClass;
console.log(hd, inst, ic, Ajv);
EOF
timeout 120 npx tsc --noEmit --strict --esModuleInterop --module nodenext --moduleResolution nodenext --target es2022 --skipLibCheck scratch-probe.ts 2>&1 | head -30; rm scratch-probe.ts

